<script lang="ts">
 import{onMount}from'svelte';import{getV6Experiment,getV6RunDetail,getV6Runs,getV6Status,type V6Experiment,type V6RunDetail,type V6Runs,type V6Status}from'../v6Api';let status=$state<V6Status|null>(null);let experiment=$state<V6Experiment|null>(null);let runs=$state<V6Runs|null>(null);let detail=$state<V6RunDetail|null>(null);let error=$state<string|null>(null);let loading=$state(true);let copyMessage=$state<string|null>(null);
 const text=(v:unknown)=>v===undefined||v===null||v===''?'MISSING':String(v);const newest=()=>runs?.runs?.[0];const dataset=()=>runs?.datasets?.find(x=>x.run_id===newest()?.dataset_run_id);const verdict=()=>detail?.manifest?.verdict_candidate??newest()?.verdict_candidate;const short=(v:unknown)=>text(v).slice(0,12);async function copy(value:unknown){try{await navigator.clipboard.writeText(text(value));copyMessage='SHA를 클립보드에 복사했습니다.'}catch{copyMessage='클립보드를 사용할 수 없습니다. SHA를 직접 복사하세요.'}}async function load(){loading=true;error=null;const[a,b,c]=await Promise.all([getV6Status(),getV6Experiment(),getV6Runs()]);if(a.ok&&a.data&&b.ok&&b.data&&c.ok&&c.data){status=a.data;experiment=b.data;runs=c.data;const r=c.data.runs?.[0];if(r?.dataset_run_id&&r.run_id){const d=await getV6RunDetail(r.dataset_run_id,r.run_id);if(d.ok&&d.data)detail=d.data;else error=d.error??'최신 실행 상세를 불러오지 못했습니다.'}}else error=a.error??b.error??c.error??'알 수 없는 오류가 발생했습니다.';loading=false}onMount(load);
</script>
<section class="page"><header><p class="eyebrow">RESEARCH PROVENANCE</p><h1>보고서</h1><p>판정과 근거의 연결만 기록합니다. 이 화면은 투자 권유나 수익 주장이 아닙니다.</p></header>{#if loading}<section class="panel">판정과 증거 체인을 확인하고 있습니다.</section>{:else if error&&!status}<section class="panel error">{error}</section>{:else}<section class:danger={text(verdict()?.value)==='NO_GO'} class="verdict"><p class="eyebrow">현재 판정</p><h2>{text(verdict()?.value)}</h2>{#each (verdict()?.reasons??[]) as reason}<p>{text(reason)}</p>{:else}<p>판정 사유가 기록되지 않았습니다.</p>{/each}</section>{#if runs?.runs?.length}<section class="chains"><section class="chain"><h2>Universe manifest</h2><code title={text(status?.journey.data.universe_manifest)}>{short(status?.journey.data.universe_manifest)}</code><button onclick={()=>copy(status?.journey.data.universe_manifest)}>복사</button><p>{text(status?.journey.data.universe_size)} rows</p></section><section class="chain"><h2>Preregistration</h2><code title={text(experiment?.prereg?.sha256)}>{short(experiment?.prereg?.sha256)}</code><button onclick={()=>copy(experiment?.prereg?.sha256)}>복사</button></section><section class="chain"><h2>Dataset run</h2><code title={text(dataset()?.sha256)}>{short(dataset()?.sha256)}</code><button onclick={()=>copy(dataset()?.sha256)}>복사</button><p>{text(dataset()?.run_id)}</p></section><section class="chain"><h2>Training manifest</h2><code title={text(detail?.manifest_sha256)}>{short(detail?.manifest_sha256)}</code><button onclick={()=>copy(detail?.manifest_sha256)}>복사</button><p>{text(newest()?.run_id)}</p></section></section>{:else}<section class="panel empty"><h2>증거 체인이 비어 있습니다</h2><p>학습 실행이 없으므로 데이터셋·학습 manifest·판정을 연결할 수 없습니다.</p></section>{/if}{#if copyMessage}<p class="copy-message">{copyMessage}</p>{/if}<section class="card rules"><h2>보고 규칙</h2><p>GO/NO-GO/INCONCLUSIVE/NOT_RUN은 그대로 기록되며 완화되지 않습니다.</p></section><section class="card"><h2>관련 문서</h2><div class="docs"><code>requirements.txt</code><code>docs/kronos_v6_prereg_h1_2026-07-19.json</code><code>docs/kronos_v6_universe_manifest_2026-07-19.json</code><code>docs/kronos_v6_goal_review_and_plan_2026-07-19.md</code></div></section>{/if}</section>
<style>.page{width:100%;color:var(--fg)}header,.panel,.card,.verdict{border:1px solid var(--border);border-radius:14px;padding:clamp(16px,4vw,28px);background:var(--surface)}.eyebrow{margin:0;color:var(--accent);font-size:.82rem;font-weight:800;letter-spacing:.1em}h1{margin:7px 0;color:var(--fg-strong);font-size:clamp(1.8rem,6vw,2.6rem)}h2{margin:0 0 12px;color:var(--fg-strong);font-size:1.15rem}.verdict,.card,.panel,.chains{margin-top:16px}.verdict h2{color:var(--info);font-size:clamp(2rem,8vw,3.5rem)}.verdict.danger{border-color:var(--danger);background:var(--danger-soft)}.verdict.danger h2,.error{color:var(--danger)}.chains{display:grid;grid-template-columns:repeat(auto-fit,minmax(420px,1fr));gap:16px}.chain{border:1px solid var(--border-strong);border-radius:10px;padding:16px;background:var(--surface-raised)}code{overflow-wrap:anywhere;color:var(--accent-strong);font-size:.85rem}.chain button{margin-left:8px}.chain p{color:var(--muted)}.rules,.empty{border-color:var(--warn);background:var(--warn-soft);color:var(--warn)}.docs{display:flex;flex-wrap:wrap;gap:8px}.docs code{border:1px solid var(--border-strong);border-radius:999px;padding:5px 8px;background:var(--surface-sunken)}button{border:1px solid var(--accent);border-radius:6px;padding:6px 10px;background:transparent;color:var(--accent-strong);font:inherit}.copy-message{color:var(--accent-strong)}</style>